39	                          PauseRecordRepository pauseRecordRepository,
40	                          ResumeRecordRepository resumeRecordRepository,
41	                          IdempotencyService idempotency, Clock clock) {
42	        this.releaseRepository = releaseRepository;
43	        this.taskRepository = taskRepository;
