1	package com.example.starter.firmware;
2	
3	import org.junit.jupiter.api.BeforeEach;
4	import org.junit.jupiter.api.Test;
5	import org.springframework.beans.factory.annotation.Autowired;
6	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
7	import org.springframework.boot.test.context.SpringBootTest;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.test.web.servlet.MockMvc;
10	import org.springframework.test.web.servlet.MvcResult;
11	
12	import static org.assertj.core.api.Assertions.assertThat;
13	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
14	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
15	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
16	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
17	
18	/**
19	 * 固件灰度投放 API 主流程、失败分支与幂等边界测试（H2 内存库，MODE=MySQL）。
20	 */
21	@SpringBootTest
22	@AutoConfigureMockMvc
23	class FirmwareApiTest {
24	
25	    @Autowired
26	    private MockMvc mockMvc;
27	
28	    @Autowired
29	    private JdbcTemplate jdbc;
30	
31	    private static long idOf(MvcResult result, String path) throws Exception {
32	        Number value = com.jayway.jsonpath.JsonPath.read(result.getResponse().getContentAsString(), path);
33	        return value.longValue();
34	    }
35	
36	    @BeforeEach
37	    void cleanUp() {
38	        jdbc.update("DELETE FROM rollout_task");
39	        jdbc.update("DELETE FROM release_pause_record");
40	        jdbc.update("DELETE FROM release_resume_record");
41	        jdbc.update("DELETE FROM release_order");
42	        jdbc.update("DELETE FROM device");
43	        jdbc.update("DELETE FROM idempotency_record");
44	    }
45	
46	    private String registerDevice(String requestId, String deviceId, String model, String version, int bucket)
47	            throws Exception {
48	        MvcResult result = mockMvc.perform(post("/api/devices")
49	                        .contentType("application/json")
50	                        .content("""
51	                                {"requestId":"%s","deviceId":"%s","model":"%s","currentVersion":"%s","bucketNo":%d}
52	                                """.formatted(requestId, deviceId, model, version, bucket)))
53	                .andReturn();
54	        return result.getResponse().getContentAsString();
55	    }
56	
57	    private String createRelease(String requestId, String model, String from, String to, int ratio)
58	            throws Exception {
59	        MvcResult result = mockMvc.perform(post("/api/releases")
60	                        .contentType("application/json")
61	                        .content("""
62	                                {"requestId":"%s","model":"%s","fromVersion":"%s","toVersion":"%s","ratio":%d}
63	                                """.formatted(requestId, model, from, to, ratio)))
64	                .andReturn();
65	        return result.getResponse().getContentAsString();
66	    }
67	
68	    private long releaseIdOf(String responseBody) {
69	        Number id = com.jayway.jsonpath.JsonPath.read(responseBody, "$.releaseId");
70	        return id.longValue();
71	    }
72	
73	    @Test
74	    void 主流程_登记发布拉取回执成功并更新设备版本() throws Exception {
75	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
76	                        {"requestId":"r1","deviceId":"d1","model":"m1","currentVersion":"1.0.0","bucketNo":5}
77	                        """))
78	                .andExpect(status().isOk())
79	                .andExpect(jsonPath("$.deviceId").value("d1"))
80	                .andExpect(jsonPath("$.bucketNo").value(5));
81	
82	        MvcResult release = mockMvc.perform(post("/api/releases").contentType("application/json").content("""
83	                        {"requestId":"r2","model":"m1","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":10}
84	                        """))
85	                .andExpect(status().isOk())
86	                .andExpect(jsonPath("$.version").value(1))
87	                .andExpect(jsonPath("$.status").value("ACTIVE"))
88	                .andReturn();
89	        long releaseId = idOf(release, "$.releaseId");
90	
91	        MvcResult pull = mockMvc.perform(post("/api/devices/d1/pull").contentType("application/json")
92	                        .content("{\"requestId\":\"r3\"}"))
93	                .andExpect(status().isOk())
94	                .andExpect(jsonPath("$.task.status").value("PENDING"))
95	                .andExpect(jsonPath("$.task.fromVersion").value("1.0.0"))
96	                .andExpect(jsonPath("$.task.toVersion").value("2.0.0"))
97	                .andReturn();
98	        long taskId = idOf(pull, "$.task.taskId");
99	
100	        mockMvc.perform(post("/api/tasks/" + taskId + "/receipt").contentType("application/json")
101	                        .content("{\"requestId\":\"r4\",\"result\":\"SUCCESS\"}"))
102	                .andExpect(status().isOk())
103	                .andExpect(jsonPath("$.status").value("SUCCESS"));
104	
105	        mockMvc.perform(get("/api/devices/d1"))
106	                .andExpect(status().isOk())
107	                .andExpect(jsonPath("$.currentVersion").value("2.0.0"));
108	
109	        mockMvc.perform(get("/api/releases/" + releaseId + "/tasks"))
110	                .andExpect(status().isOk())
111	                .andExpect(jsonPath("$.tasks.length()").value(1))
112	                .andExpect(jsonPath("$.tasks[0].status").value("SUCCESS"));
113	    }
114	
115	    @Test
116	    void 设备登记_重复设备冲突_参数校验() throws Exception {
117	        registerDevice("r1", "d1", "m1", "1.0.0", 5);
118	
119	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
120	                        {"requestId":"r2","deviceId":"d1","model":"m1","currentVersion":"1.0.0","bucketNo":5}
121	                        """))
122	                .andExpect(status().isConflict())
123	                .andExpect(jsonPath("$.code").value("DEVICE_EXISTS"));
124	
125	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
126	                        {"requestId":"r3","deviceId":"d2","model":"m1","currentVersion":"1.0.0","bucketNo":100}
127	                        """))
128	                .andExpect(status().isBadRequest());
129	
130	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
131	                        {"deviceId":"d3","model":"m1","currentVersion":"1.0.0","bucketNo":1}
132	                        """))
133	                .andExpect(status().isBadRequest());
134	    }
135	
136	    @Test
137	    void 幂等_同键同参重放原结果_异参409_失败不占键() throws Exception {
138	        String first = registerDevice("rid-1", "d1", "m1", "1.0.0", 5);
139	        assertThat(first).contains("\"deviceId\":\"d1\"");
140	
141	        String replay = registerDevice("rid-1", "d1", "m1", "1.0.0", 5);
142	        assertThat(replay).isEqualTo(first);
143	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM device", Long.class)).isEqualTo(1);
144	
145	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
146	                        {"requestId":"rid-1","deviceId":"d9","model":"m1","currentVersion":"1.0.0","bucketNo":5}
147	                        """))
148	                .andExpect(status().isConflict())
149	                .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));
150	
151	        // 失败不占键：先以错误参数触发 409，再用同 requestId 正确参数成功
152	        createRelease("rid-x", "m1", "1.0.0", "1.0.0", 10); // 400 在 Service 外，requestId 未入库
153	        MvcResult created = mockMvc.perform(post("/api/releases").contentType("application/json").content("""
154	                        {"requestId":"rid-y","model":"m1","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":10}
155	                        """))
156	                .andExpect(status().isOk())
157	                .andReturn();
158	        long releaseId = releaseIdOf(created.getResponse().getContentAsString());
159	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
160	                        {"requestId":"rid-z","expectedVersion":99,"ratio":50}
161	                        """))
162	                .andExpect(status().isConflict())
163	                .andExpect(jsonPath("$.code").value("VERSION_CONFLICT"));
164	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
165	                        {"requestId":"rid-z","expectedVersion":1,"ratio":50}
166	                        """))
167	                .andExpect(status().isOk())
168	                .andExpect(jsonPath("$.version").value(2))
169	                .andExpect(jsonPath("$.ratio").value(50));
170	    }
171	
172	    @Test
173	    void 发布单_目标来源相同400_同型号第二张ACTIVE409() throws Exception {
174	        mockMvc.perform(post("/api/releases").contentType("application/json").content("""
175	                        {"requestId":"r1","model":"m1","fromVersion":"1.0.0","toVersion":"1.0.0","ratio":10}
176	                        """))
177	                .andExpect(status().isBadRequest())
178	                .andExpect(jsonPath("$.code").value("SAME_VERSION"));
179	
180	        createRelease("r2", "m1", "1.0.0", "2.0.0", 10);
181	        mockMvc.perform(post("/api/releases").contentType("application/json").content("""
182	                        {"requestId":"r3","model":"m1","fromVersion":"1.0.0","toVersion":"3.0.0","ratio":20}
183	                        """))
184	                .andExpect(status().isConflict())
185	                .andExpect(jsonPath("$.code").value("ACTIVE_RELEASE_EXISTS"));
186	    }
187	
188	    @Test
189	    void 扩量_版本校验_比例只增不减_重放不再加版本() throws Exception {
190	        long releaseId = releaseIdOf(createRelease("r1", "m1", "1.0.0", "2.0.0", 10));
191	
192	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
193	                        {"requestId":"r2","expectedVersion":2,"ratio":30}
194	                        """))
195	                .andExpect(status().isConflict())
196	                .andExpect(jsonPath("$.code").value("VERSION_CONFLICT"));
197	
198	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
199	                        {"requestId":"r3","expectedVersion":1,"ratio":30}
200	                        """))
201	                .andExpect(status().isOk())
202	                .andExpect(jsonPath("$.version").value(2))
203	                .andExpect(jsonPath("$.ratio").value(30));
204	
205	        // 同 requestId 同参重放：版本不再增加
206	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
207	                        {"requestId":"r3","expectedVersion":1,"ratio":30}
208	                        """))
209	                .andExpect(status().isOk())
210	                .andExpect(jsonPath("$.version").value(2))
211	                .andExpect(jsonPath("$.ratio").value(30));
212	
213	        // 同 requestId 异参：409
214	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
215	                        {"requestId":"r3","expectedVersion":1,"ratio":40}
216	                        """))
217	                .andExpect(status().isConflict())
218	                .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));
219	
220	        // 比例下降：409
221	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
222	                        {"requestId":"r4","expectedVersion":2,"ratio":20}
223	                        """))
224	                .andExpect(status().isConflict())
225	                .andExpect(jsonPath("$.code").value("RATIO_DECREASE"));
226	
227	        // 比例越界：400
228	        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
229	                        {"requestId":"r5","expectedVersion":2,"ratio":101}
230	                        """))
231	                .andExpect(status().isBadRequest());
232	    }
233	
234	    @Test
235	    void 拉取_不匹配不创建任务_重复拉取返回已有任务() throws Exception {
236	        registerDevice("r1", "d1", "m1", "1.0.0", 50);
237	        registerDevice("r2", "d2", "m1", "9.9.9", 1);
238	        createRelease("r3", "m1", "1.0.0", "2.0.0", 10);
239	
240	        // 分桶号不小于比例：不投放
241	        mockMvc.perform(post("/api/devices/d1/pull").contentType("application/json")
242	                        .content("{\"requestId\":\"r4\"}"))
243	                .andExpect(status().isOk())
244	                .andExpect(jsonPath("$.task").doesNotExist());
245	
246	        // 当前版本不匹配：不投放
247	        mockMvc.perform(post("/api/devices/d2/pull").contentType("application/json")
248	                        .content("{\"requestId\":\"r5\"}"))
249	                .andExpect(status().isOk())
250	                .andExpect(jsonPath("$.task").doesNotExist());
251	
252	        // 无 ACTIVE 发布单的型号：不投放
253	        registerDevice("r6", "d3", "m2", "1.0.0", 1);
254	        mockMvc.perform(post("/api/devices/d3/pull").contentType("application/json")
255	                        .content("{\"requestId\":\"r7\"}"))
256	                .andExpect(status().isOk())
