157	    @Test
158	    void 并发拉取与取消_最终状态一致() throws Exception {
159	        for (int round = 0; round < 10; round++) {
160	            String deviceId = "d" + round;
161	            String model = "m" + round;
162	            deviceService.register(new RegisterDeviceRequest("req-d" + round, deviceId, model, "1.0.0", 5));
163	            long releaseId = releaseService.create(
164	                    new CreateReleaseRequest("req-r" + round, model, "1.0.0", "2.0.0", 100)).releaseId();
165	            final int seq = round;
166	
167	            List<Object> results = runConcurrently(List.of(
168	                    (Callable<Object>) () -> taskService.pull(deviceId, "req-p" + seq),
169	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
170	            assertThat(results).noneMatch(r -> r instanceof Exception && !(r instanceof ApiException));
