200	            String deviceVersion = deviceService.get(deviceId).currentVersion();
201	            if (finalStatus == TaskStatus.SUCCESS) {
202	                successWins++;
203	                assertThat(receiptResult).isNotInstanceOf(Exception.class);
204	                assertThat(deviceVersion).isEqualTo("2.0.0");
205	            } else {
206	                cancelWins++;
207	                assertThat(finalStatus).isEqualTo(TaskStatus.CANCELLED);
